def get_latest_file(pattern, directory):
    import glob
    files = glob.glob(os.path.join(directory, pattern))
    if not files:
        return None
    latest = max(files, key=os.path.getmtime)
    return latest

def get_status_emoji(status):
    if status == 'done':
        return '✅'
    elif status == 'in_progress':
        return '🟡'
    elif status == 'pending':
        return '⏳'
    else:
        return '⚪'

def check_book_status(base_path):
    # Check for manuscript (look for .md files that are not front matter etc.)
    manuscript_md = None
    for root, dirs, files in os.walk(base_path):
        for f in files:
            if f.endswith('.md') and not f.startswith(('FRONT', 'BACK', 'MISSION', 'PROJECT', 'PUBLISH', 'SPEC', 'tech')):
                manuscript_md = os.path.join(root, f)
                break
        if manuscript_md:
            break
    # Determine manuscript status
    manuscript_status = 'pending'
    if manuscript_md and os.path.getsize(manuscript_md) > 1000:
        manuscript_status = 'done'
    elif manuscript_md:
        manuscript_status = 'in_progress'

    # Check for EPUB
    epub_files = []
    for root, dirs, files in os.walk(base_path):
        for f in files:
            if f.endswith('.epub'):
                epub_files.append(os.path.join(root, f))
    epub_status = 'done' if epub_files else 'pending'
    latest_epub = max(epub_files, key=os.path.getmtime) if epub_files else None

    # Check for PDF
    pdf_files = []
    for root, dirs, files in os.walk(base_path):
        for f in files:
            if f.endswith('.pdf') and not 'cover' in f.lower() and not 'raw' in f.lower() and not 'print' in f.lower():
                pdf_files.append(os.path.join(root, f))
    pdf_status = 'done' if pdf_files else 'pending'
    latest_pdf = max(pdf_files, key=os.path.getmtime) if pdf_files else None

    # Check for cover images
    cover_files = []
    for root, dirs, files in os.walk(base_path):
        for f in files:
            if f.lower().endswith(('.png', '.jpg', '.jpeg')) and 'cover' in f.lower():
                cover_files.append(os.path.join(root, f))
    cover_status = 'done' if cover_files else 'pending'
    latest_cover = max(cover_files, key=os.path.getmtime) if cover_files else None

    # Count chapters
    chapter_count = 0
    for root, dirs, files in os.walk(base_path):
        if 'book-sources' in root:
            for f in files:
                if f.startswith('Chapter_') and f.endswith('.md'):
                    chapter_count += 1

    return {
        'manuscript': manuscript_status,
        'epub': epub_status,
        'pdf': pdf_status,
        'cover': cover_status,
        'chapters': chapter_count,
        'latest_epub': latest_epub,
        'latest_pdf': latest_pdf,
        'latest_cover': latest_cover
    }

